/**
 * Current UI language.
 * @returns {"fa"|"en"} Language code.
 */
function getLang() {
  return document.documentElement.lang === 'en' ? 'en' : 'fa';
}

/**
 * True if a translation exists for `key` (in the current language or English).
 * @param {string} key Translation key.
 * @returns {boolean} Exists.
 */
function hasKey(key) {
  return key in I18N[getLang()] || key in I18N.en;
}

/**
 * Translate a key and fill `{placeholders}`.
 * @param {string} key Translation key.
 * @param {Object} [vars] Values for the placeholders.
 * @returns {string} Translated text.
 */
function t(key, vars) {
  const dict = I18N[getLang()];
  let text = key in dict ? dict[key] : (key in I18N.en ? I18N.en[key] : key);
  // Values are wrapped in Unicode "first strong isolate" marks so that English file names
  // inside Persian sentences (and vice versa) keep their own direction.
  if (vars) text = text.replace(/\{(\w+)\}/g, (m, name) => (name in vars ? '\u2068' + String(vars[name]) + '\u2069' : m));
  return text;
}
